var o=`0449-rugbrau`;var t=`world-0449`;var a=`IS`;var n=`northern-europe`;var i=8;var s=808;var u={en:`Rúgbrauð`,ua:`Ісландський житній хліб`};var l={en:`A traditional dish from Iceland, centered on rye flour, whole wheat flour, rye sourdough starter. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ісландія. Основні складники: житнє борошно, цільнозернове пшеничне борошно, житня закваска. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`rye-flour`,380,`g`],[`whole-wheat-flour`,120,`g`],[`water`,460,`ml`],[`rye-sourdough-starter`,100,`g`],[`molasses`,100,`g`],[`table-salt`,10,`g`]]},{en:`Leave the rye dough covered to sour and rise for about 10 hours at room temperature; do not refrigerate at this stage.`,ua:`Залиште житнє тісто накритим на 10 годин за кімнатної температури, щоб воно заквасилося й піднялося; на цьому етапі не охолоджуйте.`,t:[`bulk-fermentation`],m:600,i:[]},{en:`Bake covered at 120–130°C for several hours, as for Icelandic slow-baked rye bread; cool fully before slicing.`,ua:`Випікайте під кришкою при 120–130°C протягом кількох годин, як ісландський повільно печений житній хліб; повністю остудіть перед нарізанням.`,t:[`roasting`],m:200,i:[]}];var g={slug:o,id:t,country:`IS`,region:n,servings:8,minutes:808,title:u,text:l,steps:d};export{a as country,g as default,t as id,s as minutes,n as region,i as servings,o as slug,d as steps,l as text,u as title};